create table admin_approval_request (approved_date timestamp(6), created_date timestamp(6) not null, expires_at timestamp(6) not null, approver_id uuid, id uuid not null, requester_id uuid not null, reason varchar(1024), action varchar(255) not null, status varchar(255) not null check (status in ('PENDING','APPROVED','REJECTED','EXPIRED')), primary key (id));
create table app_user (email_verification_completed boolean, is_active boolean not null, is_temporary boolean not null, sign_in_attempts integer not null, created_date timestamp(6) not null, deprovisioned_at timestamp(6), role_assigned_at timestamp(6), session_version bigint not null, application_id uuid unique, id uuid not null, organization_id uuid, person_id uuid unique, settings_id uuid unique, email varchar(255) not null, multifactor_authentication_type varchar(255) not null check (multifactor_authentication_type in ('SMS','EMAIL','PASSKEY','PASSWORD_RESET')), password varchar(255), password_salt varchar(255), pending_email varchar(255), pending_email_verification_code varchar(255), role varchar(255) not null check (role in ('PLATFORM_ADMIN','APPLICATION','APP_USER','ORG_ADMIN','ORG_GROUP_ADMIN','ORG_MEMBER')), role_source varchar(255), primary key (id));
create table app_user_settings (auto_preview_documents boolean not null, notify_doc_add boolean not null, notify_doc_comment boolean not null, notify_doc_delete boolean not null, notify_doc_upload boolean not null, notify_login boolean not null, notify_share_accept boolean not null, notify_share_decline boolean not null, notify_share_end boolean not null, notify_share_start boolean not null, created_date timestamp(6) not null, updated_date timestamp(6) not null, id uuid not null, primary key (id));
create table application (is_active boolean not null, created_date timestamp(6) not null, last_access_date timestamp(6), id uuid not null, api_key varchar(255) not null, api_secret varchar(255) not null, application_type varchar(255) not null check (application_type in ('WEB','MOBILE','SERVICE','INTEGRATION')), description varchar(255), name varchar(255) not null, primary key (id));
create table audit_log (timestamp timestamp(6) not null, document_id uuid not null, id uuid not null, performed_by_app_user_id uuid, action varchar(255) not null check (action in ('UPLOAD','DOWNLOAD','VIEW','CREATED','DELETE','UPDATE','COMMENT','VERSION_CREATED')), performed_by_email varchar(255) not null, primary key (id));
create table auth_audit_event (created_date timestamp(6) not null, actor_id uuid, id uuid not null, organization_id uuid, event_hash varchar(128) not null, prev_event_hash varchar(128), action_reason varchar(2048), after_snapshot varchar(4000), before_snapshot varchar(4000), action varchar(255) not null, actor_role varchar(255), outcome varchar(255) not null, reason_code varchar(255), request_id varchar(255), session_id varchar(255), target_id varchar(255), target_type varchar(255), primary key (id));
create table auth_token (created_date timestamp(6), expiry_date timestamp(6), app_user_id uuid, id uuid not null, token varchar(2048) not null, jti varchar(255) unique, otp varchar(255), token_type varchar(255) check (token_type in ('ACCESS','REFRESH','ID')), primary key (id));
create table contact_details (is_email_verified boolean, is_phone_verified boolean, created_date timestamp(6), id uuid not null, organization_id uuid unique, person_id uuid unique, email varchar(255), email_verification_code varchar(255), pending_email varchar(255), pending_phone_number varchar(255), phone_number varchar(255), phone_verification_code varchar(255), primary key (id));
create table document (encryption_mode smallint not null check (encryption_mode between 0 and 1), is_deleted boolean not null, restricted_type smallint check (restricted_type between 0 and 8), created_date timestamp(6) not null, update_date timestamp(6) not null, upload_date timestamp(6), id uuid not null, last_updated_by_id uuid unique, hash varchar(255), title varchar(255) not null, type varchar(255) check (type in ('PDF','DOCX','DOC','XLSX','XLS','PPTX','PPT','PNG','JPG')), primary key (id));
create table document_comment (created_date timestamp(6) not null, commented_by_user_id uuid not null, document_id uuid not null, id uuid not null, comment_text varchar(500) not null, primary key (id));
create table document_version (created_date timestamp(6) not null, created_by uuid, document_id uuid, id uuid not null, createdByEmail varchar(255), file_name varchar(255) not null, storage_path varchar(255) not null, version varchar(255) not null, primary key (id));
create table identity_provider_link (created_date timestamp(6) not null, app_user_id uuid not null, id uuid not null, external_email varchar(255) not null, external_subject_id varchar(255) not null, provider varchar(255) not null check (provider in ('INTERNAL','MICROSOFT','GOOGLE')), primary key (id), unique (provider, external_subject_id));
create table mfa_record (attempt_count integer, created_date timestamp(6), expiry_date timestamp(6), app_user_id uuid, id uuid not null, ip_address varchar(255), mfa_token varchar(255), mfa_type varchar(255) check (mfa_type in ('SMS','EMAIL','PASSKEY','PASSWORD_RESET')), session_id varchar(255), status varchar(255) check (status in ('PENDING','COMPLETED','LOCKED')), primary key (id));
create table organization (is_active boolean not null, verification_complete boolean not null, created_date timestamp(6) not null, contact_details_id uuid unique, id uuid not null, settings_id uuid unique, name varchar(255) not null, registration_number varchar(255) not null, primary key (id));
create table organization_group (is_active boolean not null, created_date timestamp(6) not null, id uuid not null, organization_id uuid, name varchar(255) not null, primary key (id));
create table organization_group_member (is_active boolean not null, created_date timestamp(6) not null, app_user_id uuid, id uuid not null, organization_group_id uuid, primary key (id));
create table organization_group_member_permissions (allow_document_addition boolean not null, allow_document_deletion boolean not null, allow_document_download boolean not null, allow_document_update boolean not null, allow_document_upload boolean not null, allow_session_accept boolean not null, allow_session_delete boolean not null, allow_session_edit boolean not null, allow_session_end boolean not null, allow_session_reject boolean not null, is_active boolean not null, created_date timestamp(6) not null, id uuid not null, organization_group_member_id uuid unique, primary key (id));
create table organization_identity_provider_config (is_active boolean not null, access_token_expiry_minutes bigint, created_date timestamp(6) not null, max_session_duration_hours bigint, refresh_token_expiry_days bigint, updated_date timestamp(6) not null, created_by uuid, id uuid not null, organization_id uuid not null, updated_by uuid, allowed_algs varchar(512), scopes varchar(1024), allowed_audiences varchar(2048), required_claims varchar(2048), client_id varchar(255) not null, client_secret_ref varchar(255) not null, oidc_issuer varchar(255), provider varchar(255) not null, tenant_id varchar(255), primary key (id));
create table organization_settings (allow_email_update boolean not null, allow_profile_update boolean not null, allow_share_without_pairing boolean not null, created_date timestamp(6) not null, updated_date timestamp(6) not null, id uuid not null, primary key (id));
create table organization_sharing_session_link (created_date timestamp(6) not null, linked_date timestamp(6), rejected_date timestamp(6), id uuid not null, requested_organization_id uuid not null, requesting_organization_id uuid not null, rejection_reason varchar(255), requesting_message varchar(255), status varchar(255) not null check (status in ('PENDING','ACCEPTED','REJECTED')), primary key (id));
create table organization_subscription_policy (created_date timestamp(6) not null, max_users bigint, updated_date timestamp(6) not null, id uuid not null, organization_id uuid not null, change_reason varchar(1024), tier_code varchar(255) not null, primary key (id));
create table person (created_date timestamp(6), contact_details_id uuid unique, id uuid not null, first_name varchar(255) not null, identification_number varchar(255), last_name varchar(255) not null, person_id_type varchar(255) check (person_id_type in ('ID_NUMBER','PASSPORT_NUMBER','SOCIAL_SECURITY')), primary key (id));
create table refresh_token (consumed_at timestamp(6), expires_at timestamp(6) not null, grace_until timestamp(6), issued_at timestamp(6) not null, revoked_at timestamp(6), id uuid not null, user_id uuid not null, user_session_id uuid, token_hash varchar(128) not null, family_id varchar(255) not null, jti varchar(255) not null unique, revocation_reason_code varchar(255), rotated_from_jti varchar(255), status varchar(255) not null, primary key (id));
create table security_incident (created_date timestamp(6) not null, actor_id uuid, id uuid not null, details varchar(2048), incident_type varchar(255) not null, request_id varchar(255), severity varchar(255) not null, primary key (id));
create table sharing_session (allow_document_addition boolean not null, allow_document_deletion boolean not null, allow_document_download boolean not null, allow_document_update boolean not null, allow_document_upload boolean not null, is_deleted boolean not null, require_recipient_sign_in boolean not null, created_date timestamp(6) not null, date_deleted timestamp(6), end_date timestamp(6), expire_date timestamp(6), last_activity timestamp(6) not null, group_id uuid, id uuid not null, initiator_id uuid, recipient_id uuid, description varchar(255) not null, end_note varchar(255), initial_share_message varchar(255) not null, recipient_type varchar(255) not null check (recipient_type in ('APP_USER','GROUP','EMAIL')), rejection_reason varchar(255), session_name varchar(255) not null, status varchar(255) not null check (status in ('INITIATED','ACCEPTED_STARTED','ENDED','REJECTED')), primary key (id));
create table sharing_session_document (SharingSession_id uuid not null, documents_id uuid not null unique);
create table sharing_session_participant (added_date timestamp(6) not null, app_user_id uuid, id uuid not null, organization_group_id uuid, sharing_session_id uuid not null, participant_type varchar(255) not null check (participant_type in ('GROUP','APP_USER')), primary key (id));
create table sign_up (otp_attempts integer not null, otp_regeneration_attempts integer not null, created_at timestamp(6) not null, last_regeneration_attempt_time timestamp(6), otp_expiry_timestamp timestamp(6) not null, id uuid not null, email varchar(255) not null unique, otp varchar(255) not null, status varchar(255) not null check (status in ('PENDING','VERIFIED','EXPIRED','EXPIRED_MAX_RETRIES','OTP_LOCKED')), primary key (id));
create table user_session (is_active boolean not null, created_date timestamp(6) not null, expires_at timestamp(6), last_auth_time timestamp(6) not null, last_seen_at timestamp(6) not null, revoked_at timestamp(6), app_user_id uuid not null, organization_id uuid, revoked_by_user_id uuid, session_id uuid not null, risk_flags varchar(1024), user_agent varchar(1024), device_id varchar(255), device_name varchar(255), ip_address varchar(255), revocation_reason_code varchar(255), primary key (session_id));
